use kimo_core::{color::{bake::{Chain,Step},lut::Lut},effects::Frame,keyframe::Prop};
fn effect(k:&str,ps:&[(&str,f64)])->Step{Step::Effect{kind:k.into(),params:ps.iter().map(|(k,v)|((*k).into(),Prop::new(*v))).collect(),strings:Default::default()}}
#[test]fn affine_roundtrip_all_sizes(){let c=Chain::new(vec![effect("exposure",&[("stops",1.)]),effect("contrast",&[("amount",0.8)])],0.).unwrap();for n in [17,33,65]{let l=c.bake(n,[0.;3],[1.;3]).unwrap();let path=format!("/tmp/bake-affine-{}-{n}.cube",std::process::id());c.write(&l,&path).unwrap();let l=Lut::parse(&std::fs::read_to_string(path).unwrap()).unwrap();for i in 0..1000{let rgb=[(i%97) as f32/96.,(i%43) as f32/42.,(i%17) as f32/16.];let mut f=Frame{w:1,h:1,d:vec![rgb[0],rgb[1],rgb[2],1.]};c.apply(&mut f).unwrap();let a=l.sample(rgb);for j in 0..3{assert!((a[j]-f.d[j]).abs()<8e-7);}}}}
#[test]fn rejects_nonpointwise_and_bad_domains(){for kind in ["grain","glow","halation","film_finish","vignette","denoise"]{assert!(Chain::new(vec![effect(kind,&[])],0.).is_err());}let c=Chain::new(vec![effect("exposure",&[])],0.).unwrap();assert!(c.bake(32,[0.;3],[1.;3]).is_err());assert!(c.bake(17,[1.;3],[1.;3]).is_err());}
#[cfg(feature="native-ocio")]
#[test]fn native_ocio_bake_node_identity_and_view(){let path=concat!(env!("CARGO_MANIFEST_DIR"),"/tests/data/minimal_aces.ocio");let c=Chain::new(vec![Step::Ocio{config_path:path.into(),source:"ACEScg".into(),destination:"ACEScct".into()}],0.).unwrap();let l=c.bake(17,[0.;3],[1.;3]).unwrap();for i in 0..17{let x=i as f32/16.;let mut f=Frame{w:1,h:1,d:vec![x,x,x,1.]};c.apply(&mut f).unwrap();let y=l.sample([x;3]);assert!((y[0]-f.d[0]).abs()<1e-7);}if let Ok(path)=std::env::var("KIMO_TEST_NATIVE_ACES_CONFIG"){let c=Chain::new(vec![Step::OcioView{config_path:path,source:"ACEScg".into(),display:"sRGB - Display".into(),view:"ACES 2.0 - SDR 100 nits (Rec.709)".into()}],0.).unwrap();assert!(c.bake(17,[0.;3],[1.;3]).is_ok());}}
#[test]fn mcp_bake_no_project_mutation(){use kimo_core::commands::{Session,dispatch};use serde_json::json;let mut s=Session::new();let before=serde_json::to_value(&s.project).unwrap();let p=format!("/tmp/bake-tool-{}.cube",std::process::id());let r=dispatch(&mut s,"export_color_pipeline_lut",&json!({"steps":[{"type":"effect","kind":"exposure","params":{"stops":{"base":1}}}],"size":17,"path":p})).unwrap();assert_eq!(r["entries"],4913);assert_eq!(before,serde_json::to_value(&s.project).unwrap());}
